* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  min-height: 100vh;
  color: white;
}

.app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 20px;
}

header {
  text-align: center;
  margin-bottom: 40px;
}

header h1 {
  font-size: 3rem;
  margin-bottom: 10px;
  text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
}

header p {
  font-size: 1.2rem;
  opacity: 0.9;
}

main {
  background: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(10px);
  border-radius: 20px;
  padding: 30px;
  min-width: 400px;
  max-width: 500px;
  box-shadow: 0 8px 32px rgba(0,0,0,0.2);
}

.game-info {
  display: flex;
  justify-content: space-between;
  margin-bottom: 30px;
}

.stat {
  text-align: center;
}

.stat label {
  display: block;
  font-size: 0.9rem;
  opacity: 0.8;
  margin-bottom: 5px;
}

.score {
  font-size: 2rem;
  font-weight: bold;
  color: #ffeb3b;
}

.stat span {
  font-size: 1.5rem;
  font-weight: bold;
}

.price-display {
  text-align: center;
  margin-bottom: 30px;
  padding: 20px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 15px;
}

.price-display h2 {
  font-size: 1.5rem;
  margin-bottom: 10px;
  opacity: 0.9;
}

.current-price {
  font-size: 2.5rem;
  font-weight: bold;
  color: #4caf50;
  margin-bottom: 10px;
}

.start-price {
  font-size: 1rem;
  opacity: 0.7;
}

.game-controls {
  text-align: center;
}

.timer {
  font-size: 1.5rem;
  font-weight: bold;
  margin-bottom: 20px;
  color: #ffeb3b;
}

.prediction-buttons {
  display: flex;
  gap: 20px;
  justify-content: center;
  margin-bottom: 20px;
}

.predict-btn {
  padding: 15px 30px;
  font-size: 1.2rem;
  font-weight: bold;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  transition: all 0.3s ease;
  min-width: 120px;
}

.predict-btn.up {
  background: linear-gradient(135deg, #4caf50, #45a049);
  color: white;
}

.predict-btn.down {
  background: linear-gradient(135deg, #f44336, #d32f2f);
  color: white;
}

.predict-btn:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 4px 8px rgba(0,0,0,0.3);
}

.predict-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
}

.predict-btn.selected {
  transform: scale(1.1);
  box-shadow: 0 0 20px rgba(255,255,255,0.5);
}

.prediction-status {
  background: rgba(255, 255, 255, 0.1);
  padding: 15px;
  border-radius: 10px;
  margin-top: 10px;
}

.round-result {
  text-align: center;
  padding: 20px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 15px;
}

.round-result h3 {
  font-size: 2rem;
  margin-bottom: 10px;
}

.round-result p {
  font-size: 1.1rem;
  margin-bottom: 10px;
}

.waiting, .loading {
  text-align: center;
  padding: 40px;
  font-size: 1.2rem;
}

.loading {
  opacity: 0.7;
}

@media (max-width: 480px) {
  main {
    min-width: 300px;
    padding: 20px;
  }

  header h1 {
    font-size: 2rem;
  }

  .current-price {
    font-size: 2rem;
  }

  .prediction-buttons {
    flex-direction: column;
    gap: 10px;
  }

  .predict-btn {
    min-width: 100%;
  }
}

