import './App.css'

// Pyth MCP integration
async function pythMCP(toolName, args) {
  // Step 1: Initialize session
  const init = await fetch('https://mcp.pyth.network/mcp', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream' },
    body: JSON.stringify({
      jsonrpc: '2.0', id: 0, method: 'initialize',
      params: { protocolVersion: '2024-11-05', capabilities: {}, clientInfo: { name: 'bonjour-app', version: '1.0' } }
    })
  });
  await init.json();

  // Step 2: Call the tool
  const res = await fetch('https://mcp.pyth.network/mcp', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream' },
    body: JSON.stringify({
      jsonrpc: '2.0', id: 1, method: 'tools/call',
      params: { name: toolName, arguments: args }
    })
  });
  const data = await res.json();
  const text = data.result?.content?.[0]?.text || '';
  return JSON.parse(text);
}

function App() {
  const [btcPrice, setBtcPrice] = useState(null)
  const [roundStartPrice, setRoundStartPrice] = useState(null)
  const [timeLeft, setTimeLeft] = useState(60)
  const [prediction, setPrediction] = useState(null)
  const [score, setScore] = useState(0)
  const [lastResult, setLastResult] = useState(null)
  const [isRoundActive, setIsRoundActive] = useState(false)
  const [roundNumber, setRoundNumber] = useState(1)

  // Fetch live BTC price
  const fetchBTCPrice = useCallback(async () => {
    try {
      const result = await pythMCP('get_candlestick_data', {
        symbol: 'Crypto.BTC/USD',
        resolution: '1',
        hours_back: 1
      })

      if (result.candles && result.candles.length > 0) {
        const latestCandle = result.candles[result.candles.length - 1]
        setBtcPrice(latestCandle.close)
      }
    } catch (error) {
      console.error('Failed to fetch BTC price:', error)
    }
  }, [])

  // Start new round
  const startNewRound = useCallback(() => {
    if (btcPrice) {
      setRoundStartPrice(btcPrice)
      setTimeLeft(60)
      setPrediction(null)
      setLastResult(null)
      setIsRoundActive(true)
    }
  }, [btcPrice])

  // End round and calculate result
  const endRound = useCallback(() => {
    if (roundStartPrice && btcPrice && prediction) {
      const priceChange = btcPrice - roundStartPrice
      const actualDirection = priceChange > 0 ? 'UP' : 'DOWN'
      const isCorrect = prediction === actualDirection

      if (isCorrect) {
        setScore(prev => prev + 10)
        setLastResult({ correct: true, change: priceChange })
      } else {
        setLastResult({ correct: false, change: priceChange })
      }
    } else if (prediction) {
      setLastResult({ correct: false, change: 0, noPrediction: true })
    }

    setIsRoundActive(false)
    setRoundNumber(prev => prev + 1)

    // Auto-start next round after 3 seconds
    setTimeout(() => {
      startNewRound()
    }, 3000)
  }, [roundStartPrice, btcPrice, prediction, startNewRound])

  // Timer countdown
  useEffect(() => {
    if (isRoundActive && timeLeft > 0) {
      const timer = setTimeout(() => {
        setTimeLeft(prev => prev - 1)
      }, 1000)
      return () => clearTimeout(timer)
    } else if (isRoundActive && timeLeft === 0) {
      endRound()
    }
  }, [timeLeft, isRoundActive, endRound])

  // Fetch price every 2 seconds
  useEffect(() => {
    fetchBTCPrice()
    const interval = setInterval(fetchBTCPrice, 2000)
    return () => clearInterval(interval)
  }, [fetchBTCPrice])

  // Auto-start first round when price loads
  useEffect(() => {
    if (btcPrice && !isRoundActive && roundNumber === 1 && !lastResult) {
      startNewRound()
    }
  }, [btcPrice, isRoundActive, roundNumber, lastResult, startNewRound])

  const makePrediction = (direction) => {
    if (isRoundActive && !prediction) {
      setPrediction(direction)
    }
  }

  return (
    <div className="app">
      <header>
        <h1>🚀 Bonjour</h1>
        <p>Predict Bitcoin's price direction in 1 minute!</p>
      </header>

      <main>
        <div className="game-info">
          <div className="stat">
            <label>Score</label>
            <span className="score">{score}</span>
          </div>
          <div className="stat">
            <label>Round</label>
            <span>{roundNumber}</span>
          </div>
        </div>

        <div className="price-display">
          <h2>Bitcoin Price</h2>
          <div className="current-price">
            ${btcPrice ? btcPrice.toLocaleString('en-US', { minimumFractionDigits: 2 }) : '---'}
          </div>
          {roundStartPrice && (
            <div className="start-price">
              Round started at: ${roundStartPrice.toLocaleString('en-US', { minimumFractionDigits: 2 })}
            </div>
          )}
        </div>

        {isRoundActive && (
          <div className="game-controls">
            <div className="timer">
              Time left: {timeLeft}s
            </div>

            <div className="prediction-buttons">
              <button 
                className={`predict-btn up ${prediction === 'UP' ? 'selected' : ''}`}
                onClick={() => makePrediction('UP')}
                disabled={!!prediction}
              >
                📈 UP
              </button>
              <button 
                className={`predict-btn down ${prediction === 'DOWN' ? 'selected' : ''}`}
                onClick={() => makePrediction('DOWN')}
                disabled={!!prediction}
              >
                📉 DOWN
              </button>
            </div>

            {prediction && (
              <div className="prediction-status">
                You predicted: <strong>{prediction}</strong>
                <br />
                <small>Locked in! Wait for the round to end...</small>
              </div>
            )}
          </div>
        )}

        {!isRoundActive && lastResult && (
          <div className="round-result">
            <h3>{lastResult.correct ? '🎉 Correct!' : '❌ Wrong!'}</h3>
            <p>
              Price {lastResult.change > 0 ? 'went UP' : lastResult.change < 0 ? 'went DOWN' : 'stayed the same'} 
              {lastResult.change !== 0 && (
                <span> by ${Math.abs(lastResult.change).toFixed(2)}</span>
              )}
            </p>
            {lastResult.correct && <p>+10 points!</p>}
            <small>Next round starting in 3 seconds...</small>
          </div>
        )}

        {!isRoundActive && !lastResult && btcPrice && (
          <div className="waiting">
            <p>Starting first round...</p>
          </div>
        )}

        {!btcPrice && (
          <div className="loading">
            <p>Loading Bitcoin price...</p>
          </div>
        )}
      </main>
    </div>
  )
}

export default App"}

